import{_ as a,c as I,o as e,b0 as l}from"./chunks/framework.C5ev1SXp.js";const d="data:image/svg+xml;base64,",t="data:image/svg+xml;base64,",m=JSON.parse('{"title":"LV007-内存分配与碎片","description":null,"frontmatter":{"title":"LV007-内存分配与碎片","date":"2026-11-18T18:23:04.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/rtos/rtos-memory/126d68c083a00019c443bbaf","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-18T18:23:04.001Z","fulluuid":"9c443bbaf16147b0aada8eaf5ccd3053","useduuid":"9c443bbaf"}},"headers":[],"relativePath":"sdoc/advanced-chapter/rtos/rtos-memory/126d68c083a00019c443bbaf.md","filePath":"sdoc/30-进阶篇/90-FreeRTOS/03-内存管理/LV007-内存分配与碎片.md","lastUpdated":1795000891000}'),s={name:"sdoc/advanced-chapter/rtos/rtos-memory/126d68c083a00019c443bbaf.md"};function o(n,i,c,g,h,r){return e(),I("div",null,[...i[0]||(i[0]=[l('<h1 id="lv007-内存分配与碎片" tabindex="-1">LV007-内存分配与碎片 <a class="header-anchor" href="#lv007-内存分配与碎片" aria-label="Permalink to &quot;LV007-内存分配与碎片&quot;">​</a></h1><h2 id="一、-分配与释放" tabindex="-1">一、 分配与释放 <a class="header-anchor" href="#一、-分配与释放" aria-label="Permalink to &quot;一、 分配与释放&quot;">​</a></h2><h3 id="_1-分配流程" tabindex="-1">1. 分配流程 <a class="header-anchor" href="#_1-分配流程" aria-label="Permalink to &quot;1. 分配流程&quot;">​</a></h3><h4 id="_1-1-首次适配" tabindex="-1">1.1 首次适配 <a class="header-anchor" href="#_1-1-首次适配" aria-label="Permalink to &quot;1.1 首次适配&quot;">​</a></h4><p><code>pvPortMalloc()</code> 从头遍历空闲链表，找到第一个足够大的块就切一块出来，剩余部分重新挂回链表。整个过程包在临界区里，因此可以被任务与中断安全调用。</p><p>由于是&quot;第一个够用的&quot;，堆里可能同时存在多个可用空洞而只用了最靠前的一个——这也是碎片容易积累的原因之一。</p><h4 id="_1-2-分配失败的三种原因" tabindex="-1">1.2 分配失败的三种原因 <a class="header-anchor" href="#_1-2-分配失败的三种原因" aria-label="Permalink to &quot;1.2 分配失败的三种原因&quot;">​</a></h4><p>申请失败返回 <code>NULL</code>，常见原因有三：</p><ul><li><p>空闲总量确实不够</p></li><li><p>总量够但最大连续块不够（碎片）</p></li><li><p>堆已被反复申请释放打散，链表里全是很小的洞</p></li></ul><p>第一种看 <code>free</code> 就够，后两种必须看空闲链表的分布。</p><h3 id="_2-释放流程" tabindex="-1">2. 释放流程 <a class="header-anchor" href="#_2-释放流程" aria-label="Permalink to &quot;2. 释放流程&quot;">​</a></h3><h4 id="_2-1-相邻合并" tabindex="-1">2.1 相邻合并 <a class="header-anchor" href="#_2-1-相邻合并" aria-label="Permalink to &quot;2.1 相邻合并&quot;">​</a></h4><p>释放时先清掉块头的分配标志，然后检查前后邻居是否也空闲，能合就合：</p><p><img src="'+d+`" alt="释放时的相邻合并"></p><p>这是 <code>heap_4</code> 相比 <code>heap_2</code> 最关键的改进。<code>heap_2</code> 不合并，释放出的块只能被不大于它的申请复用，时间一长堆里全是小洞；<code>heap_4</code> 通过合并维持大块，显著延缓碎片化。</p><h4 id="_2-2-线程安全边界" tabindex="-1">2.2 线程安全边界 <a class="header-anchor" href="#_2-2-线程安全边界" aria-label="Permalink to &quot;2.2 线程安全边界&quot;">​</a></h4><p><code>heap_4</code> 内部用 <code>vTaskSuspendAll()</code> 保护链表操作，任务与中断里都可以调用。但不是所有 API 都这样——<code>xPortGetFreeHeapSize()</code> 只是读一个变量，不加锁；<code>xPortGetMinimumEverFreeHeapSize()</code> 同理，读取时可能拿到瞬间不一致的值，调试用足够。</p><h2 id="二、-查询与统计" tabindex="-1">二、 查询与统计 <a class="header-anchor" href="#二、-查询与统计" aria-label="Permalink to &quot;二、 查询与统计&quot;">​</a></h2><h3 id="_1-两个查询-api" tabindex="-1">1. 两个查询 API <a class="header-anchor" href="#_1-两个查询-api" aria-label="Permalink to &quot;1. 两个查询 API&quot;">​</a></h3><h4 id="_1-1-当前空闲量是遍历得来的" tabindex="-1">1.1 当前空闲量是遍历得来的 <a class="header-anchor" href="#_1-1-当前空闲量是遍历得来的" aria-label="Permalink to &quot;1.1 当前空闲量是遍历得来的&quot;">​</a></h4><p><code>xPortGetFreeHeapSize()</code> 遍历空闲链表把各块大小累加。返回的是<strong>总空闲量</strong>，不是<strong>最大连续可用块</strong>；两者只有在堆完全没碎片时才相等。</p><h4 id="_1-2-历史最低值怎么维护" tabindex="-1">1.2 历史最低值怎么维护 <a class="header-anchor" href="#_1-2-历史最低值怎么维护" aria-label="Permalink to &quot;1.2 历史最低值怎么维护&quot;">​</a></h4><p><code>xPortGetMinimumEverFreeHeapSize()</code> 返回 <code>xMinimumEverFreeBytesRemaining</code>，每次分配后顺手更新，记录开机以来最紧张的时刻：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Middlewares/Third_Party/FreeRTOS/Source/portable/MemMang/heap_4.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( xFreeBytesRemaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xMinimumEverFreeBytesRemaining ) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    xMinimumEverFreeBytesRemaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xFreeBytesRemaining;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>它比当前值更有参考价值：峰值需求往往只发生一瞬间，事后看当前值是看不出问题的。</p><h3 id="_2-动态任务的影响" tabindex="-1">2. 动态任务的影响 <a class="header-anchor" href="#_2-动态任务的影响" aria-label="Permalink to &quot;2. 动态任务的影响&quot;">​</a></h3><h4 id="_2-1-一个任务的成本" tabindex="-1">2.1 一个任务的成本 <a class="header-anchor" href="#_2-1-一个任务的成本" aria-label="Permalink to &quot;2.1 一个任务的成本&quot;">​</a></h4><p>固件里的 <code>burn</code> 命令会动态创建一个 CPU 密集任务，参数是 192 字栈：</p><table tabindex="0"><thead><tr><th>组成</th><th>字节</th></tr></thead><tbody><tr><td>栈（192 字）</td><td>768</td></tr><tr><td>TCB</td><td>96</td></tr><tr><td>块头（栈 + TCB）</td><td>16</td></tr><tr><td>合计</td><td>880</td></tr></tbody></table><p>实测 <code>free</code> 从 4168 降到 3288，差值正好 880，与计算吻合。</p><h4 id="_2-2-删除后的归还" tabindex="-1">2.2 删除后的归还 <a class="header-anchor" href="#_2-2-删除后的归还" aria-label="Permalink to &quot;2.2 删除后的归还&quot;">​</a></h4><p><code>burn</code> 跑完调用 <code>vTaskDelete(NULL)</code> 删除自己，栈与 TCB 立即归还堆，空闲量回到 4168。若这块恰好与相邻空闲块接壤，还会被合并。</p><p>需要注意：<strong>任务删除后 <code>top</code> 里它的累计运行时间一并消失</strong>，因为 TCB 被回收。此时各项 CPU 占比之和会小于 100%，缺的那部分就是已删除任务的耗时。</p><h4 id="_2-3-历史最低值不会回弹" tabindex="-1">2.3 历史最低值不会回弹 <a class="header-anchor" href="#_2-3-历史最低值不会回弹" aria-label="Permalink to &quot;2.3 历史最低值不会回弹&quot;">​</a></h4><p>任务删除后 <code>heap free</code> 恢复到 4168，但 <code>heap min</code> 仍停在 3288。它记录的是&quot;堆曾经被压到多低&quot;，用来判断余量是否够撑住峰值。</p><h2 id="三、-碎片" tabindex="-1">三、 碎片 <a class="header-anchor" href="#三、-碎片" aria-label="Permalink to &quot;三、 碎片&quot;">​</a></h2><h3 id="_1-成因" tabindex="-1">1. 成因 <a class="header-anchor" href="#_1-成因" aria-label="Permalink to &quot;1. 成因&quot;">​</a></h3><p><img src="`+t+`" alt="碎片导致分配失败"></p><h4 id="_1-1-典型场景" tabindex="-1">1.1 典型场景 <a class="header-anchor" href="#_1-1-典型场景" aria-label="Permalink to &quot;1.1 典型场景&quot;">​</a></h4><p>动态创建、删除不同栈大小的任务，或在运行时反复申请释放不同长度的缓冲区，都会把连续的堆切成一段段。</p><h4 id="_1-2-为什么合并救不了" tabindex="-1">1.2 为什么合并救不了 <a class="header-anchor" href="#_1-2-为什么合并救不了" aria-label="Permalink to &quot;1.2 为什么合并救不了&quot;">​</a></h4><p>即使 <code>heap_4</code> 会合并相邻空闲块，只要中间隔着仍被占用的块，合并就无从谈起。碎片不是算法缺陷，而是&quot;长期按不同尺寸分配&quot;的必然结果。</p><h3 id="_2-判断与缓解" tabindex="-1">2. 判断与缓解 <a class="header-anchor" href="#_2-判断与缓解" aria-label="Permalink to &quot;2. 判断与缓解&quot;">​</a></h3><h4 id="_2-1-量化碎片" tabindex="-1">2.1 量化碎片 <a class="header-anchor" href="#_2-1-量化碎片" aria-label="Permalink to &quot;2.1 量化碎片&quot;">​</a></h4><p>解析空闲链表：用最大空闲块除以空闲总量，比值远小于 1 就说明已经很碎。本工程当前只有一个空闲块，比值是 1，属于最健康的状态。</p><h4 id="_2-2-四种缓解手段" tabindex="-1">2.2 四种缓解手段 <a class="header-anchor" href="#_2-2-四种缓解手段" aria-label="Permalink to &quot;2.2 四种缓解手段&quot;">​</a></h4><ul><li><p>优先使用<strong>静态分配</strong>：<code>osThreadNew</code> 传入 <code>stack_mem</code>/<code>cb_mem</code>，或用 <code>xTaskCreateStatic</code></p></li><li><p>把 <code>configTOTAL_HEAP_SIZE</code> 一次性给足，避免运行期&quot;刚够用&quot;</p></li><li><p>尽量让申请尺寸固定（例如统一用同一档栈大小），减少尺寸多样性</p></li><li><p>在 <code>vApplicationMallocFailedHook</code> 里记录现场，而不是让它静默返回 <code>NULL</code></p></li></ul><h2 id="四、-观测手段与后续" tabindex="-1">四、 观测手段与后续 <a class="header-anchor" href="#四、-观测手段与后续" aria-label="Permalink to &quot;四、 观测手段与后续&quot;">​</a></h2><h3 id="_1-导出堆并逐块解析" tabindex="-1">1. 导出堆并逐块解析 <a class="header-anchor" href="#_1-导出堆并逐块解析" aria-label="Permalink to &quot;1. 导出堆并逐块解析&quot;">​</a></h3><p>用 J-Link 把整块堆导出成文件，再按块头遍历：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>; J-Link 命令脚本（长度参数按十六进制解析）</span></span>
<span class="line"><span>h</span></span>
<span class="line"><span>savebin $TEMP\\heap.bin 0x200012C0 0x2000</span></span>
<span class="line"><span>go</span></span>
<span class="line"><span>exit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>遍历规则：读块头取 <code>xBlockSize</code>，清掉最高位得块长度，用户数据从块首加 8 字节开始，下一块从当前块首加块长度处开始。</p><h3 id="_2-可继续深入的问题" tabindex="-1">2. 可继续深入的问题 <a class="header-anchor" href="#_2-可继续深入的问题" aria-label="Permalink to &quot;2. 可继续深入的问题&quot;">​</a></h3><ul><li><p><code>heap_2</code>、<code>heap_5</code> 的适用场景与碎片表现差异</p></li><li><p>长时间运行后空闲链表的块数量变化，量化碎片程度</p></li><li><p><code>vApplicationMallocFailedHook</code> 的实际触发路径与降级策略</p></li><li><p>是否值得为长期稳定运行的任务改用静态分配，彻底绕开堆</p></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,56)])])}const b=a(s,[["render",o]]);export{m as __pageData,b as default};
